class Solution {
public:
    long long maxSum(vector<int>& nums, int m, int k) {
        unordered_map<int, int> counts;
        long long curr_sum = 0, ans = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            counts[nums[i]]++;
            curr_sum += nums[i];
            if (i >= k) {
                int out = nums[i - k];
                if (--counts[out] == 0) counts.erase(out);
                curr_sum -= out;
            }
            if (i >= k - 1 && counts.size() >= m) {
                ans = max(ans, curr_sum);
            }
        }
        return ans;
    }
};

class Solution {
    public long maxSum(List<Integer> nums, int m, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        long currSum = 0, ans = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            int x = nums.get(i);
            counts.put(x, counts.getOrDefault(x, 0) + 1);
            currSum += x;
            if (i >= k) {
                int out = nums.get(i - k);
                int c = counts.get(out);
                if (c == 1) counts.remove(out);
                else counts.put(out, c - 1);
                currSum -= out;
            }
            if (i >= k - 1 && counts.size() >= m) {
                ans = Math.max(ans, currSum);
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} m
 * @param {number} k
 * @return {number}
 */
var maxSum = function(nums, m, k) {
    const counts = new Map();
    let currSum = 0, ans = 0;
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        const x = nums[i];
        counts.set(x, (counts.get(x) || 0) + 1);
        currSum += x;
        if (i >= k) {
            const out = nums[i - k];
            const c = counts.get(out);
            if (c === 1) counts.delete(out);
            else counts.set(out, c - 1);
            currSum -= out;
        }
        if (i >= k - 1 && counts.size >= m) {
            if (currSum > ans) ans = currSum;
        }
    }
    return ans;
};
